process.env.GITHUB_REPOSITORY = 'acme/widgets';
const assert = require('node:assert/strict');
const test = require('node:test');

const reconcile = require('./factory-visibility.cjs');
const { verdictOf, verdictAt } = require('./factory-outside-verdict.cjs');

const HEAD = 'e644b292d35b9af9480dda648cfa54a73f6b7a91';
const OLD = '1a3ba212b96c25adb377ff5fef6cdc5b78ec6b08';
const OWNER = { login: 'acme', type: 'User' };
const MODEL = 'Model: Sonnet 5.5 (claude-sonnet-5-5)';
const FOOTER = '---\n_Generated by [Claude Code](https://claude.ai/code)_';

function summary(verdict, head = HEAD) {
  return `Outside review summary for head \`${head.slice(0, 12)}\`: 4 ruff errors.\n\n${MODEL}\nVerdict: ${verdict}\n\n${FOOTER}`;
}

function ownerReview(body, { commit = HEAD, at = '2026-11-25T17:22:27Z' } = {}) {
  return {
    id: 6061983957, user: OWNER, author_association: 'OWNER', state: 'COMMENTED',
    commit_id: commit, submitted_at: at, body,
    html_url: 'https://github.com/acme/widgets/pull/100#pullrequestreview-6061983957',
  };
}

function githubFor({ labels = ['factory', 'factory:review', 'factory:unowned'], reviews = [], comments = [], writes }) {
  return {
    graphql: async () => ({
      repository: { pullRequest: { reviewThreads: { nodes: [], pageInfo: { hasNextPage: false } }, comments: { nodes: comments.map(comment => ({
        body: comment.body, url: 'https://github.com/acme/widgets/pull/100#issuecomment-1',
        createdAt: comment.created_at || '2026-11-25T17:22:29Z',
        authorAssociation: comment.author_association || 'OWNER',
        author: { __typename: comment.bot ? 'Bot' : 'User', login: comment.login || 'acme' },
      })) } } },
    }),
    rest: {
      issues: {
        listLabelsOnIssue: async () => ({ data: labels.map(name => ({ name })), headers: {}, status: 200 }),
        listComments: async () => ({ data: [], headers: {}, status: 200 }),
        setLabels: async params => {
          writes.push(params);
          return { data: {}, headers: {}, status: 200 };
        },
      },
      checks: { listForRef: async () => ({ data: { check_runs: [] } }) },
      pulls: {
        listReviews: async ({ page }) => ({ data: page === 1 ? reviews : [], headers: {}, status: 200 }),
        get: async params => ({
          data: {
            number: params.pull_number, state: 'open', body: '', mergeable: true,
            head: { sha: HEAD, ref: 'feature/rust-roll', repo: { full_name: 'acme/widgets' } },
          },
        }),
      },
    },
  };
}

function reviewEvent(review) {
  return {
    eventName: 'pull_request_review',
    repo: { owner: 'acme', repo: 'widgets' },
    payload: {
      action: 'submitted',
      repository: { full_name: 'acme/widgets' },
      pull_request: { number: 100, head: { ref: 'feature/rust-roll', sha: HEAD, repo: { full_name: 'acme/widgets' } } },
      review,
    },
  };
}

function commentEvent(body) {
  return {
    eventName: 'issue_comment',
    repo: { owner: 'acme', repo: 'widgets' },
    payload: {
      action: 'created',
      repository: { full_name: 'acme/widgets' },
      issue: { number: 100, pull_request: {}, body: '' },
      comment: { body, user: OWNER, author_association: 'OWNER', performed_via_github_app: { slug: 'claude' } },
    },
  };
}

async function run(context, options) {
  const writes = [];
  await reconcile({ github: githubFor({ ...options, writes }), context });
  return writes;
}

test('the verdict is the last line, after the connector footer, with a Model line', () => {
  assert.equal(verdictOf(summary('changes-requested')), 'changes-requested');
  assert.equal(verdictOf(summary('approve')), 'approve');
  assert.equal(verdictOf(`${MODEL}\nVerdict: approve`), 'approve');
  assert.equal(verdictOf('Verdict: approve'), null);
  assert.equal(verdictOf(`${MODEL}\nVerdict: approve\nOne more line.`), null);
  assert.equal(verdictOf(`${MODEL}\n> Verdict: approve`), null);
  assert.equal(verdictOf(`${MODEL}\n  Verdict: approve`), null);
});

test('a verdict quoted inside a code fence is ignored', () => {
  assert.equal(verdictOf(`${MODEL}\n\`\`\`text\nVerdict: changes-requested\n\`\`\``), null);
  assert.equal(verdictOf(`${MODEL}\n\`\`\`\nVerdict: changes-requested`), null);
  assert.equal(verdictOf(`\`\`\`\n${MODEL}\n\`\`\`\nVerdict: approve`), null);
});

test('changes-requested on the current head moves the PR to factory:changes-requested', async () => {
  const review = ownerReview(summary('changes-requested'));
  const writes = await run(reviewEvent(review), { reviews: [review] });
  assert.equal(writes.length, 1);
  assert.ok(writes[0].labels.includes('factory:changes-requested'));
  assert.ok(!writes[0].labels.includes('factory:review'));
  assert.ok(!writes[0].labels.includes('factory:approved'));
});

test('a summary comment naming the current head routes from the comment event', async () => {
  const body = summary('changes-requested');
  const writes = await run(commentEvent(body), { comments: [{ body }] });
  assert.equal(writes.length, 1);
  assert.ok(writes[0].labels.includes('factory:changes-requested'));
});

test('a verdict on an older head is ignored', async () => {
  const review = ownerReview(summary('changes-requested', OLD), { commit: OLD });
  assert.deepEqual(await run(reviewEvent(review), { reviews: [review] }), []);
  const body = summary('changes-requested', OLD);
  assert.deepEqual(await run(commentEvent(body), { comments: [{ body }] }), []);
});

test('an outside approve moves no label in the reconciler script; the approval step decides', async () => {
  const review = ownerReview(summary('approve'));
  const writes = await run(reviewEvent(review), { reviews: [review] });
  assert.deepEqual(writes, []);
  const found = verdictAt({ reviews: [review], head: HEAD, owner: 'acme', markerPrefix: 'widgets' });
  assert.equal(found.verdict, 'approve');
});

test('bot and factory-marker comments never carry a verdict', async () => {
  const body = summary('changes-requested');
  const bot = { body, login: 'github-actions[bot]', bot: true, author_association: 'NONE' };
  assert.deepEqual(await run(commentEvent(body), { comments: [bot] }), []);
  const marked = `<!-- widgets-factory-review-v2:${HEAD}:pass -->\n${body}`;
  assert.equal(verdictAt({ comments: [{ body: marked, user: OWNER }], head: HEAD, owner: 'acme', markerPrefix: 'widgets' }), null);
});

test('the latest owner verdict at the head wins', () => {
  const early = ownerReview(summary('changes-requested'), { at: '2026-11-25T17:00:00Z' });
  const late = ownerReview(summary('approve'), { at: '2026-11-25T18:00:00Z' });
  const found = verdictAt({ reviews: [early, late], head: HEAD, owner: 'acme', markerPrefix: 'widgets' });
  assert.equal(found.verdict, 'approve');
});
